"""Compact summary of the literal saved trace-map transcript for ALL four cases and both faces; lists what is present/absent. No assertions."""
import glob, os
import sympy as sp
from sympy import *  # noqa
try:
    from sympy.core.symbol import Str
except ImportError:
    Str = lambda s: Symbol(s)
W = os.getcwd()
rec = {}; order = []
for f in sorted(glob.glob(W + '/input/source-excerpts/*c2_trace_repair_maps.out-*.txt')):
    for ln in open(f).read().splitlines():
        if ln.startswith('Tuple('):
            r = eval(ln); d = {str(a[0]): a[1] for a in r}
            k = str(d['writeKey']).replace('s11cc2TraceRepair', ''); rec[k] = (d['value'], d); order.append(k)
print("total records:", len(rec))
cases = sorted({k.split('Plus')[0].split('Minus')[0] for k in rec})
for c in cases:
    for nm in ('Plus', 'Minus'):
        keys = [k for k in rec if k.startswith(c + nm)]
        short = lambda k: str(rec[c + nm + k][0]) if c + nm + k in rec else 'ABSENT'
        print("\n##", c, nm, "records:", len(keys))
        for k in ('Source', 'ValueCoefficient', 'NormalJetCoefficient', 'HeightConstant', 'ReferenceNormalMultiplier', 'TwoLegTraceOperator',
                  'TwoLegTraceResidual', 'ThreeLegTraceResidual', 'TraceReconstructionResidual', 'HeightReconstructionResidual',
                  'ReferenceValueSolveResidual'):
            print("   %-30s %s" % (k, short(k)[:200]))
        for k in ('ThreeLegFaceResponse', 'ThreeLegTraceOperator', 'ThreeLegReferenceResponse', 'ThreeLegReferenceResponseBeforeProjection', 'ReferenceMixedKernel', 'TwoLegFaceResponse', 'TwoLegReferenceResponse'):
            v = rec.get(c + nm + k)
            if v is None:
                print("   %-30s ABSENT from supplied transcript" % k)
            else:
                val = v[0]
                kind = 'fingerprint/placeholder' if (not hasattr(val, 'free_symbols')) or str(val)[:12].startswith('Tuple(') else 'literal'
                print("   %-30s present, str length %d (%s)" % (k, len(str(val)), kind))
        nz = [k for k in keys if ('Sourcetraceresidual' in k)]
        print("   SourceTraceResidual entries:", len(nz), " nonzero:", [k for k in nz if rec[k][0] != 0])
        # does the retained trace contain any wave-field (u, zeta) shift term?  list free symbols of Source
        print("   Source free symbols:", sorted(s.name for s in rec[c + nm + 'Source'][0].free_symbols) if c + nm + 'Source' in rec else 'n/a')
# what are the metadata multigrade/units for the mixed kernel
k = cases[0] + 'Plus' + 'ReferenceMixedKernel'
if k in rec:
    print("\nReferenceMixedKernel multigrade:", rec[k][1].get('multigrade'))
